@Composable
fun AdvancedPlayerSurface(
    channel: Channel?,
    preferences: PlaybackPreferences,
    muted: Boolean = false,
    preferredCandidateIndex: Int = 0
) {
    when (channel?.source) {
        ChannelSource.HLS,
        ChannelSource.IPTV -> AdvancedStreamSurface(
            channel = channel,
            preferences = preferences,
            muted = muted,
            preferredCandidateIndex = preferredCandidateIndex
        )
        else -> AdvancedIdleSurface()
    }
}

@Composable
private fun AdvancedStreamSurface(
    channel: Channel,
    preferences: PlaybackPreferences,
    muted: Boolean,
    preferredCandidateIndex: Int
) {
    val context = LocalContext.current
    val candidates = remember(channel.id, channel.uri, channel.backupUris) {
        channel.playbackUris()
    }
    var candidateIndex by remember(channel.id, preferredCandidateIndex, candidates.size) {
        mutableIntStateOf(
            preferredCandidateIndex.coerceIn(0, (candidates.size - 1).coerceAtLeast(0))
        )
    }

    if (candidates.isEmpty()) {
        AdvancedIdleSurface()
        return
    }

    val player = remember {
        val loadControl = DefaultLoadControl.Builder()
            .setBufferDurationsMs(1_500, 14_000, 350, 800)
            .build()

        val renderersFactory = DefaultRenderersFactory(context)
            .setEnableDecoderFallback(true)

        ExoPlayer.Builder(context, renderersFactory)
            .setLoadControl(loadControl)
            .build()
            .apply {
                playWhenReady = true
                setHandleAudioBecomingNoisy(true)
            }
    }

    val mediaSession = remember(player, muted) {
        if (muted) null else MediaSession.Builder(context, player).build()
    }

    LaunchedEffect(
        muted,
        preferences.subtitlesEnabled,
        preferences.preferredAudioLanguage,
        preferences.preferredSubtitleLanguage
    ) {
        player.volume = if (muted) 0f else 1f
        player.trackSelectionParameters = player.trackSelectionParameters
            .buildUpon()
            .setPreferredAudioLanguages(
                preferences.preferredAudioLanguage,
                "pt-BR",
                "pt",
                "por"
            )
            .setPreferredTextLanguages(
                preferences.preferredSubtitleLanguage,
                "pt-BR",
                "pt",
                "por"
            )
            .setSelectTextByDefault(preferences.subtitlesEnabled)
            .setSelectUndeterminedTextLanguage(preferences.subtitlesEnabled)
            .setTrackTypeDisabled(C.TRACK_TYPE_TEXT, !preferences.subtitlesEnabled)
            .build()
    }

    DisposableEffect(player, candidates.size) {
        val listener = object : Player.Listener {
            override fun onPlayerError(error: PlaybackException) {
                if (candidateIndex < candidates.lastIndex) {
                    candidateIndex += 1
                }
            }
        }
        player.addListener(listener)
        onDispose { player.removeListener(listener) }
    }

    val uri = candidates[candidateIndex.coerceIn(0, candidates.lastIndex)]

    LaunchedEffect(channel.id, uri) {
        val lower = uri.lowercase()
        val metadata = MediaMetadata.Builder()
            .setTitle(channel.name)
            .setSubtitle(channel.sourceName.ifBlank { "SANCHESTV" })
            .setArtworkUri(channel.logoUri?.let(android.net.Uri::parse))
            .build()

        val item = MediaItem.Builder()
            .setUri(uri)
            .setMediaMetadata(metadata)
            .apply {
                when {
                    ".m3u8" in lower -> setMimeType(MimeTypes.APPLICATION_M3U8)
                    ".mpd" in lower -> setMimeType(MimeTypes.APPLICATION_MPD)
                }
            }
            .build()

        player.stop()
        player.clearMediaItems()
        player.setMediaItem(item)
        player.prepare()
        player.play()
    }

    DisposableEffect(mediaSession, player) {
        onDispose {
            mediaSession?.release()
            player.release()
        }
    }

    AndroidView(
        factory = {
            PlayerView(it).apply {
                useController = false
                resizeMode = AspectRatioFrameLayout.RESIZE_MODE_FIT
                setShowBuffering(PlayerView.SHOW_BUFFERING_WHEN_PLAYING)
                this.player = player
            }
        },
        update = { it.player = player },
        modifier = Modifier
            .fillMaxSize()
            .background(Color.Black)
    )
}

@Composable
private fun AdvancedIdleSurface() {
    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.radialGradient(
                    colors = listOf(Color(0xFF12212C), SanchesColors.Background),
                    radius = 1500f
                )
            )
    )
}

