@Composable
fun ChannelNavigatorScreen(
    state: AppUiState,
    controller: ZappController
) {
    var section by remember { mutableStateOf(controller.navigatorCategory) }
    var query by remember { mutableStateOf("") }
    var letter by remember { mutableStateOf<String?>(null) }
    var focusedId by remember {
        mutableStateOf(controller.navigatorFocusId ?: state.currentChannel?.id)
    }
    var previewChannel by remember { mutableStateOf<Channel?>(null) }

    val sections = remember(state.channels, state.programs) {
        val availableCategories = ChannelClassifier.primaryCategories.filter { category ->
            state.channels.any { ChannelClassifier.category(it) == category }
        }
        buildList {
            addAll(listOf("Todos", "Favoritos", "Recentes", "Mais assistidos", "Com EPG", "Multi-fonte", "A-Z"))
            addAll(availableCategories)
        }.distinct()
    }

    val base = remember(
        state.channels,
        state.favorites,
        state.recentChannelIds,
        state.mostWatchedIds,
        section
    ) {
        when (section) {
            "Favoritos" -> state.channels.filter { it.id in state.favorites }
            "Recentes" -> channelsByIds(state.channels, state.recentChannelIds)
            "Mais assistidos" -> channelsByIds(state.channels, state.mostWatchedIds)
            "Com EPG" -> state.channels.filter { state.programs[it.id] != null }
                .sortedBy { ChannelResolver.normalize(it.name) }
            "Multi-fonte" -> state.channels.filter { it.playbackUris().size > 1 }
                .sortedBy { ChannelResolver.normalize(it.name) }
            "A-Z", "Todos" -> state.channels.sortedBy { ChannelResolver.normalize(it.name) }
            else -> state.channels
                .filter { ChannelClassifier.category(it) == section }
                .sortedBy { ChannelResolver.normalize(it.name) }
        }
    }

    val filtered = remember(base, query, letter, state.programs) {
        val q = ChannelResolver.normalize(query)
        base.filter { channel ->
            val program = state.programs[channel.id]
            val queryMatch = q.isBlank() ||
                ChannelResolver.normalize(channel.name).contains(q) ||
                ChannelResolver.normalize(channel.category).contains(q) ||
                ChannelResolver.normalize(program?.title.orEmpty()).contains(q) ||
                ChannelResolver.normalize(program?.nextTitle.orEmpty()).contains(q)
            val first = ChannelResolver.normalize(channel.name)
                .firstOrNull()
                ?.uppercaseChar()
                ?.toString()
            queryMatch && (letter == null || first == letter)
        }
    }

    val focused = filtered.firstOrNull { it.id == focusedId }
        ?: state.channels.firstOrNull { it.id == focusedId }
        ?: filtered.firstOrNull()

    LaunchedEffect(focused?.id) {
        previewChannel = null
        if (focused != null) {
            delay(600)
            previewChannel = focused
        }
    }

    Row(
        modifier = Modifier
            .fillMaxSize()
            .padding(20.dp),
        horizontalArrangement = Arrangement.spacedBy(13.dp)
    ) {
        CategoryPanel(
            sections = sections,
            selected = section,
            onSelected = { selected ->
                section = selected
                query = ""
                letter = null
                controller.rememberNavigator(selected, null)
            }
        )

        Column(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
        ) {
            Text(
                section,
                color = SanchesColors.PrimaryText,
                fontSize = 27.sp,
                fontWeight = FontWeight.Black
            )
            Text(
                filtered.size.toString() + " canais • segure ↑/↓ para rolar",
                color = SanchesColors.SecondaryText,
                fontSize = 12.sp
            )

            Spacer(Modifier.height(8.dp))

            OutlinedTextField(
                value = query,
                onValueChange = { query = it },
                singleLine = true,
                label = { Text("Filtrar por nome") },
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(Modifier.height(7.dp))

            LazyRow(horizontalArrangement = Arrangement.spacedBy(5.dp)) {
                item {
                    NavigatorChip("Todos", letter == null) { letter = null }
                }
                items(('A'..'Z').map(Char::toString)) { item ->
                    NavigatorChip(item, letter == item) { letter = item }
                }
            }

            Spacer(Modifier.height(8.dp))

            LazyColumn(
                modifier = Modifier.fillMaxSize(),
                verticalArrangement = Arrangement.spacedBy(6.dp)
            ) {
                items(filtered, key = { it.id }) { channel ->
                    NavigatorChannelItem(
                        channel = channel,
                        program = state.programs[channel.id],
                        favorite = channel.id in state.favorites,
                        selected = channel.id == state.currentChannel?.id,
                        onFocused = {
                            focusedId = channel.id
                            controller.rememberNavigator(section, channel.id)
                        },
                        onWatch = { controller.select(channel) },
                        onFavorite = { controller.toggleFavorite(channel) }
                    )
                }
            }
        }

        NavigatorPreview(
            channel = focused,
            previewChannel = previewChannel,
            program = focused?.let { state.programs[it.id] },
            favorite = focused?.id in state.favorites,
            onWatch = { focused?.let(controller::select) },
            onFavorite = { focused?.let(controller::toggleFavorite) }
        )
    }
}

@Composable
private fun CategoryPanel(
    sections: List<String>,
    selected: String,
    onSelected: (String) -> Unit
) {
    Column(
        modifier = Modifier
            .width(178.dp)
            .fillMaxHeight()
            .clip(RoundedCornerShape(20.dp))
            .background(Color(0xB30A0F14))
            .padding(10.dp)
    ) {
        Text(
            "NAVEGAR",
            color = SanchesColors.Muted,
            fontSize = 11.sp,
            fontWeight = FontWeight.Black,
            letterSpacing = 2.sp,
            modifier = Modifier.padding(8.dp)
        )

        LazyColumn(verticalArrangement = Arrangement.spacedBy(5.dp)) {
            items(sections) { item ->
                var focused by remember { mutableStateOf(false) }
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(42.dp)
                        .clip(RoundedCornerShape(12.dp))
                        .background(
                            when {
                                focused -> SanchesColors.Focus
                                selected == item -> SanchesColors.AccentStrong
                                else -> Color.Transparent
                            }
                        )
                        .onFocusChanged { focused = it.isFocused }
                        .clickable { onSelected(item) }
                        .focusable()
                        .padding(horizontal = 12.dp),
                    contentAlignment = Alignment.CenterStart
                ) {
                    Text(
                        item,
                        color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
                        fontSize = 14.sp,
                        fontWeight = if (selected == item) FontWeight.Black else FontWeight.SemiBold,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                }
            }
        }
    }
}

@Composable
private fun NavigatorChip(
    label: String,
    selected: Boolean,
    onClick: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }

    Box(
        modifier = Modifier
            .height(34.dp)
            .clip(RoundedCornerShape(10.dp))
            .background(
                when {
                    focused -> SanchesColors.Focus
                    selected -> SanchesColors.AccentStrong
                    else -> SanchesColors.SurfaceStrong
                }
            )
            .onFocusChanged { focused = it.isFocused }
            .clickable(onClick = onClick)
            .focusable()
            .padding(horizontal = 10.dp),
        contentAlignment = Alignment.Center
    ) {
        Text(
            label,
            color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
            fontSize = 11.sp,
            fontWeight = FontWeight.Bold
        )
    }
}

@Composable
private fun NavigatorChannelItem(
    channel: Channel,
    program: ProgramInfo?,
    favorite: Boolean,
    selected: Boolean,
    onFocused: () -> Unit,
    onWatch: () -> Unit,
    onFavorite: () -> Unit
) {
    var focused by remember { mutableStateOf(false) }

    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(82.dp)
            .clip(RoundedCornerShape(15.dp))
            .background(
                when {
                    focused -> SanchesColors.Focus
                    selected -> Color(0xFF183140)
                    else -> SanchesColors.Surface
                }
            )
            .onFocusChanged {
                focused = it.isFocused
                if (it.isFocused) onFocused()
            }
            .clickable(onClick = onWatch)
            .focusable()
            .padding(horizontal = 12.dp),
        verticalAlignment = Alignment.CenterVertically
    ) {
        SanchesChannelLogo(channel, Modifier.size(50.dp))
        Spacer(Modifier.width(10.dp))

        Text(
            channel.number,
            modifier = Modifier.width(54.dp),
            color = if (focused) {
                SanchesColors.FocusText.copy(alpha = .62f)
            } else {
                SanchesColors.Accent
            },
            fontSize = 12.sp,
            fontWeight = FontWeight.Bold
        )

        Column(Modifier.weight(1f)) {
            Text(
                channel.name,
                color = if (focused) SanchesColors.FocusText else SanchesColors.PrimaryText,
                fontSize = 16.sp,
                fontWeight = FontWeight.Bold,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            Text(
                program?.title ?: ChannelClassifier.category(channel),
                color = if (focused) {
                    SanchesColors.FocusText.copy(alpha = .68f)
                } else {
                    SanchesColors.SecondaryText
                },
                fontSize = 11.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis
            )
            program?.nextTitle?.let { nextTitle ->
                Text(
                    "Depois: " + nextTitle,
                    color = if (focused) {
                        SanchesColors.FocusText.copy(alpha = .5f)
                    } else {
                        SanchesColors.Muted
                    },
                    fontSize = 10.sp,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis
                )
            }
        }

        if (channel.playbackUris().size > 1) {
            Text(
                channel.playbackUris().size.toString() + "×",
                color = if (focused) SanchesColors.FocusText.copy(alpha = .6f) else SanchesColors.Muted,
                fontSize = 11.sp
            )
            Spacer(Modifier.width(6.dp))
        }

        Text(
            if (favorite) "★" else "☆",
            color = if (focused) SanchesColors.FocusText else SanchesColors.Accent,
            fontSize = 19.sp,
            modifier = Modifier
                .clickable(onClick = onFavorite)
                .padding(8.dp)
        )
    }
}

@Composable
private fun NavigatorPreview(
    channel: Channel?,
    previewChannel: Channel?,
    program: ProgramInfo?,
    favorite: Boolean,
    onWatch: () -> Unit,
    onFavorite: () -> Unit
) {
    Column(
        modifier = Modifier
            .width(390.dp)
            .fillMaxHeight()
            .clip(RoundedCornerShape(22.dp))
            .background(Color(0xD90A0F14))
            .padding(16.dp)
    ) {
        Box(
            modifier = Modifier
                .fillMaxWidth()
                .aspectRatio(16f / 9f)
                .clip(RoundedCornerShape(16.dp))
                .background(Color.Black)
        ) {
            if (previewChannel != null) {
                PlayerSurface(previewChannel, muted = true)
            } else {
                Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    channel?.let {
                        SanchesChannelLogo(it, Modifier.size(100.dp))
                    }
                }
            }

            Text(
                "PRÉVIA",
                modifier = Modifier
                    .align(Alignment.TopStart)
                    .padding(10.dp)
                    .clip(RoundedCornerShape(8.dp))
                    .background(Color(0xCC05070A))
                    .padding(horizontal = 8.dp, vertical = 4.dp),
                color = SanchesColors.Accent,
                fontSize = 10.sp,
                fontWeight = FontWeight.Black
            )
        }

        Spacer(Modifier.height(15.dp))

        Text(
            channel?.name ?: "Selecione um canal",
            color = SanchesColors.PrimaryText,
            fontSize = 22.sp,
            fontWeight = FontWeight.Black,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )

        Text(
            program?.title ?: "Ao vivo",
            color = SanchesColors.SecondaryText,
            fontSize = 14.sp,
            maxLines = 2,
            overflow = TextOverflow.Ellipsis
        )

        program?.nextTitle?.let { nextTitle ->
            Text(
                "A seguir: " + nextTitle,
                color = SanchesColors.Muted,
                fontSize = 12.sp,
                maxLines = 2,
                overflow = TextOverflow.Ellipsis
            )
        }

        Spacer(Modifier.height(13.dp))

        if (channel != null) {
            PreviewMeta("Categoria", ChannelClassifier.category(channel))
            PreviewMeta("Fonte", channel.sourceName.ifBlank { "SANCHESTV" })
            PreviewMeta("Streams", channel.playbackUris().size.toString())
            PreviewMeta("Fontes", channel.sourceCount().toString())
            PreviewMeta("Canal", channel.number)
        }

        Spacer(Modifier.weight(1f))

        NavigatorAction("Assistir agora", onWatch)
