@Composable
fun ExpandedSportsScreen(
    state: AppUiState,
    onSelect: (Channel) -> Unit,
    onFavorite: (Channel) -> Unit
) {
    val sports = state.channels.filter(::isSportsChannelV23)
    val now = System.currentTimeMillis()
    val horizon = now + 12L * 60L * 60L * 1000L
    val scheduledMatches = sports
        .flatMap { channel ->
            state.schedule[channel.id]
                .orEmpty()
                .filter { program ->
                    looksLikeMatch(program.title) &&
                        (program.endMillis ?: Long.MAX_VALUE) > now &&
                        (program.startMillis ?: now) < horizon
                }
                .map { program -> channel to program }
        }
        .distinctBy { event ->
            "${event.first.id}|${event.second.startMillis}|${event.second.title}"
        }
        .sortedBy { it.second.startMillis ?: Long.MAX_VALUE }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 28.dp, vertical = 24.dp)
    ) {
        ExpandedSectionTitle(
            "Esportes & partidas",
            if (scheduledMatches.isEmpty()) {
                "${sports.size} canais esportivos identificados"
            } else {
                "${scheduledMatches.size} jogos/eventos detectados nas próximas 12h"
            }
        )
        Spacer(Modifier.height(14.dp))

        when {
            scheduledMatches.isNotEmpty() -> {
                LazyColumn(verticalArrangement = Arrangement.spacedBy(7.dp)) {
                    items(
                        scheduledMatches,
                        key = { event ->
                            "${event.first.id}:${event.second.startMillis}:${event.second.title}"
                        }
                    ) { event ->
                        val channel = event.first
                        val program = event.second
                        val runningNow =
                            (program.startMillis ?: Long.MAX_VALUE) <= now &&
                                (program.endMillis ?: Long.MIN_VALUE) > now

                        ExpandedChannelRow(
                            channel = channel,
                            program = program,
                            favorite = channel.id in state.favorites,
                            badge = if (runningNow) {
                                "AGORA"
                            } else {
                                program.startMillis?.let(::formatTimeV23) ?: "JOGO"
                            },
                            onSelect = { onSelect(channel) },
                            onFavorite = { onFavorite(channel) }
                        )
                    }
                }
            }

            sports.isEmpty() -> {
                ExpandedEmpty("Nenhum canal esportivo foi identificado nas fontes atuais.")
            }

            else -> {
                LazyColumn(verticalArrangement = Arrangement.spacedBy(7.dp)) {
                    items(sports, key = { it.id }) { channel ->
                        ExpandedChannelRow(
                            channel = channel,
                            program = state.programs[channel.id],
                            favorite = channel.id in state.favorites,
                            badge = "ESPORTE",
                            onSelect = { onSelect(channel) },
                            onFavorite = { onFavorite(channel) }
                        )
                    }
                }
            }
        }
    }
}

