@Composable
fun ExpandedSearchScreen(
    state: AppUiState,
    history: List<String>,
    onSelect: (Channel, String) -> Unit,
    onClearHistory: () -> Unit
) {
    var query by remember { mutableStateOf("") }
    val normalized = ChannelResolver.normalize(query)
    val filtered = if (normalized.isBlank()) {
        state.channels.take(100)
    } else {
        state.channels.filter { channel ->
            ChannelResolver.normalize(channel.name).contains(normalized) ||
                ChannelResolver.normalize(channel.category).contains(normalized) ||
                ChannelResolver.normalize(channel.sourceName).contains(normalized) ||
                ChannelResolver.normalize(state.programs[channel.id]?.title.orEmpty()).contains(normalized) ||
                state.schedule[channel.id].orEmpty().any { program ->
                    ChannelResolver.normalize(program.title).contains(normalized)
                }
        }.take(300)
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 28.dp, vertical = 24.dp)
    ) {
        ExpandedSectionTitle("Buscar", "Canais, categorias, fontes e programação")
