                    favorite = channel.id in state.favorites,
                    onSelect = { onSelect(channel, query) },
                    onFavorite = {}
                )
            }
        }
    }
}

@Composable
fun ExpandedDownloadsScreen(
    downloads: FeatureDownloads,
    currentChannel: Channel?,
    onDownloadCurrent: (Result<Long>) -> Unit
) {
    var revision by remember { mutableIntStateOf(0) }
    LaunchedEffect(Unit) {
        while (true) {
            delay(1600)
            revision += 1
        }
    }
    val downloadItems = remember(revision) { downloads.list() }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .padding(horizontal = 28.dp, vertical = 24.dp)
    ) {
        ExpandedSectionTitle(
            "Downloads",
            "Arquivos VOD/progressivos ficam salvos no armazenamento do app"
        )
        Spacer(Modifier.height(12.dp))

        ExpandedAction(
            label = currentChannel?.let { "Baixar: ${it.name}" } ?: "Nenhuma mídia selecionada",
            enabled = currentChannel != null
        ) {
            currentChannel?.let { onDownloadCurrent(downloads.enqueue(it)) }
            revision += 1
        }

        Spacer(Modifier.height(14.dp))

        if (downloadItems.isEmpty()) {
            ExpandedEmpty(
                "Ainda não há downloads. Streams ao vivo HLS/DASH não são tratados como arquivo único."
            )
        } else {
            LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp)) {
                items(downloadItems, key = { it.id }) { item ->
                    DownloadRow(item) {
                        downloads.remove(item.id)
                        revision += 1
                    }
                }
            }
        }
    }
}

