fun channelsByIdsV23(channels: List<Channel>, ids: List<String>): List<Channel> {
    val map = channels.associateBy { it.id }
    return ids.mapNotNull(map::get).distinctBy { it.id }
}

fun isMovieChannelV23(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("${channel.category} ${channel.name}")
    return listOf("MOVIE", "FILME", "CINEMA", "FILMS").any { token -> value.contains(token) }
}

fun isSeriesChannelV23(channel: Channel): Boolean {
    val value = ChannelResolver.normalize("${channel.category} ${channel.name}")
    return listOf("SERIE", "SERIES", "NOVELA", "DRAMA", "ENTRETENIMENTO", "ENTERTAINMENT")
        .any { token -> value.contains(token) }
}

fun isSportsChannelV23(channel: Channel): Boolean {
    val value = ChannelResolver.normalize(
        "${channel.category} ${channel.name} ${channel.sourceName}"
    )
    return ChannelClassifier.category(channel) == "Esportes" ||
        listOf("SPORT", "ESPORTE", "FUTEBOL", "FOOTBALL", "SOCCER", "NBA", "NFL", "UFC")
            .any { token -> value.contains(token) }
}

private fun looksLikeMatch(title: String): Boolean {
    val value = ChannelResolver.normalize(title)
    if (value.isBlank()) return false
    return " VS " in " $value " ||
        " X " in " $value " ||
        listOf("FINAL", "CAMPEONATO", "COPA", "LIGA", "MATCH", "JOGO")
            .any(value::contains)
}

private fun programTimeV23(program: ProgramInfo?): String? {
    val start = program?.startMillis ?: return null
    val end = program.endMillis ?: return null
    return "${formatTimeV23(start)} – ${formatTimeV23(end)}"
}

private fun formatTimeV23(value: Long): String =
    SimpleDateFormat("HH:mm", Locale("pt", "BR")).format(Date(value))

private fun formatDateTimeV23(value: Long): String =
    SimpleDateFormat("dd/MM HH:mm", Locale("pt", "BR")).format(Date(value))

private fun languageOptions(): List<Pair<String, String>> = listOf(
    "pt-BR" to "Português BR",
    "pt" to "Português",
    "en" to "English",
    "es" to "Español"
)

